// RINEX Navigation File Parser
// Handles RINEX v2 and v3 GPS broadcast ephemeris data

class RinexParser {
  static parseNavigationFile(rinexData) {
    const lines = rinexData.split('\n');
    const satellites = [];
    let currentSat = null;
    let lineCount = 0;
    
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      
      // Skip header lines
      if (line.includes('END OF HEADER')) {
        continue;
      }
      
      // Check if this is a satellite record start (PRN line)
      if (this.isSatelliteRecord(line)) {
        if (currentSat) {
          satellites.push(currentSat);
        }
        currentSat = this.parseSatelliteHeader(line);
        lineCount = 0;
        continue;
      }
      
      // Parse ephemeris data lines
      if (currentSat && lineCount < 7) {
        this.parseEphemerisLine(currentSat, line, lineCount);
        lineCount++;
      }
    }
    
    // Add the last satellite
    if (currentSat) {
      satellites.push(currentSat);
    }
    
    return satellites;
  }
  
  static isSatelliteRecord(line) {
    // RINEX v2: PRN starts at column 0-2
    // RINEX v3: PRN starts with 'G' for GPS
    return line.length > 20 && (
      /^\s*\d{1,2}\s+\d{2}\s+\d{1,2}\s+\d{1,2}/.test(line) || // RINEX v2
      /^G\d{2}\s+\d{4}\s+\d{1,2}\s+\d{1,2}/.test(line) // RINEX v3
    );
  }
  
  static parseSatelliteHeader(line) {
    const fields = line.trim().split(/\s+/);
    let prn, year, month, day, hour, minute, second;
    
    if (line.startsWith('G')) {
      // RINEX v3 format
      prn = parseInt(fields[0].substring(1));
      year = parseInt(fields[1]);
      month = parseInt(fields[2]);
      day = parseInt(fields[3]);
      hour = parseInt(fields[4]);
      minute = parseInt(fields[5]);
      second = parseFloat(fields[6]);
    } else {
      // RINEX v2 format
      prn = parseInt(fields[0]);
      year = parseInt(fields[1]);
      month = parseInt(fields[2]);
      day = parseInt(fields[3]);
      hour = parseInt(fields[4]);
      minute = parseInt(fields[5]);
      second = parseFloat(fields[6]);
    }
    
    // Convert 2-digit year to 4-digit
    if (year < 80) {
      year += 2000;
    } else if (year < 100) {
      year += 1900;
    }
    
    const epoch = new Date(year, month - 1, day, hour, minute, second).getTime();
    
    return {
      prn,
      epoch,
      clockBias: this.parseScientificNotation(fields[7]),
      clockDrift: this.parseScientificNotation(fields[8]),
      clockDriftRate: this.parseScientificNotation(fields[9])
    };
  }
  
  static parseEphemerisLine(satellite, line, lineIndex) {
    if (!line.trim()) return;
    
    const fields = line.trim().split(/\s+/);
    
    switch (lineIndex) {
      case 0: // IODE, Crs, Delta n, M0
        satellite.iode = this.parseScientificNotation(fields[0]);
        satellite.crs = this.parseScientificNotation(fields[1]);
        satellite.deltaN = this.parseScientificNotation(fields[2]);
        satellite.meanAnomaly = this.parseScientificNotation(fields[3]);
        break;
        
      case 1: // Cuc, e, Cus, sqrt(A)
        satellite.cuc = this.parseScientificNotation(fields[0]);
        satellite.eccentricity = this.parseScientificNotation(fields[1]);
        satellite.cus = this.parseScientificNotation(fields[2]);
        satellite.sqrtA = this.parseScientificNotation(fields[3]);
        satellite.semiMajorAxis = Math.pow(satellite.sqrtA, 2);
        break;
        
      case 2: // Toe, Cic, OMEGA, Cis
        satellite.toe = this.parseScientificNotation(fields[0]);
        satellite.cic = this.parseScientificNotation(fields[1]);
        satellite.raan = this.parseScientificNotation(fields[2]); // Right Ascension of Ascending Node
        satellite.cis = this.parseScientificNotation(fields[3]);
        break;
        
      case 3: // i0, Crc, omega, OMEGA DOT
        satellite.inclination = this.parseScientificNotation(fields[0]);
        satellite.crc = this.parseScientificNotation(fields[1]);
        satellite.argOfPerigee = this.parseScientificNotation(fields[2]);
        satellite.raanDot = this.parseScientificNotation(fields[3]);
        break;
        
      case 4: // IDOT, Codes on L2, GPS Week, L2 P data flag
        satellite.inclinationDot = this.parseScientificNotation(fields[0]);
        satellite.codesOnL2 = this.parseScientificNotation(fields[1]);
        satellite.gpsWeek = this.parseScientificNotation(fields[2]);
        satellite.l2PDataFlag = this.parseScientificNotation(fields[3]);
        break;
        
      case 5: // SV accuracy, SV health, TGD, IODC
        satellite.svAccuracy = this.parseScientificNotation(fields[0]);
        satellite.svHealth = this.parseScientificNotation(fields[1]);
        satellite.tgd = this.parseScientificNotation(fields[2]);
        satellite.iodc = this.parseScientificNotation(fields[3]);
        break;
        
      case 6: // Transmission time, fit interval
        satellite.transmissionTime = this.parseScientificNotation(fields[0]);
        if (fields.length > 1) {
          satellite.fitInterval = this.parseScientificNotation(fields[1]);
        }
        break;
    }
  }
  
  static parseScientificNotation(str) {
    if (!str) return 0;
    
    // Handle RINEX scientific notation format (e.g., "1.234567890123D-04")
    const cleanStr = str.replace('D', 'E').replace('d', 'e');
    return parseFloat(cleanStr) || 0;
  }
  
  // Convert GPS week and time of week to JavaScript Date
  static gpsTimeToDate(gpsWeek, tow) {
    const gpsEpoch = new Date('1980-01-06T00:00:00.000Z');
    const msInWeek = 7 * 24 * 60 * 60 * 1000;
    const msInSecond = 1000;
    
    return new Date(gpsEpoch.getTime() + gpsWeek * msInWeek + tow * msInSecond);
  }
  
  // Fetch ephemeris data from NASA CDDIS archive
  static async fetchEphemerisData(date = new Date()) {
    try {
      // Format date for CDDIS archive path
      const year = date.getFullYear();
      const dayOfYear = this.getDayOfYear(date);
      const formattedDay = dayOfYear.toString().padStart(3, '0');
      
      // CDDIS archive URL structure
      const baseUrl = 'https://cddis.nasa.gov/archive/gnss/data/daily';
      const url = `${baseUrl}/${year}/${formattedDay}/${year.toString().slice(-2)}n/brdc${formattedDay}0.${year.toString().slice(-2)}n.Z`;
      
      // Note: Direct fetching from CDDIS requires handling CORS and authentication
      // In a production environment, you would need a backend proxy
      console.log('Ephemeris data URL:', url);
      
      // For now, return sample data
      return this.generateSampleData();
      
    } catch (error) {
      console.error('Error fetching ephemeris data:', error);
      return this.generateSampleData();
    }
  }
  
  static getDayOfYear(date) {
    const start = new Date(date.getFullYear(), 0, 0);
    const diff = date - start;
    const oneDay = 1000 * 60 * 60 * 24;
    return Math.floor(diff / oneDay);
  }
  
  static generateSampleData() {
    // Generate realistic GPS constellation data
    const satellites = [];
    const baseElements = {
      semiMajorAxis: 26559752, // meters (GPS orbit radius)
      eccentricity: 0.007,
      inclination: 0.9599, // ~55 degrees in radians
    };
    
    // Generate 24 satellites in 6 orbital planes
    for (let plane = 0; plane < 6; plane++) {
      for (let sat = 0; sat < 4; sat++) {
        const prn = plane * 4 + sat + 1;
        const raan = (plane * 60) * Math.PI / 180; // 60 degrees apart
        const meanAnomaly = (sat * 90) * Math.PI / 180; // 90 degrees apart in each plane
        
        satellites.push({
          prn,
          ...baseElements,
          eccentricity: baseElements.eccentricity + (Math.random() - 0.5) * 0.004,
          inclination: baseElements.inclination + (Math.random() - 0.5) * 0.1,
          raan,
          argOfPerigee: Math.random() * 2 * Math.PI,
          meanAnomaly,
          epoch: Date.now(),
          // Additional RINEX fields
          toe: 0,
          crs: 0, crc: 0, cuc: 0, cus: 0, cic: 0, cis: 0,
          deltaN: 0,
          inclinationDot: 0,
          raanDot: -2.6e-9, // Typical GPS RAAN drift
          sqrtA: Math.sqrt(baseElements.semiMajorAxis),
          gpsWeek: Math.floor((Date.now() - new Date('1980-01-06').getTime()) / (7 * 24 * 60 * 60 * 1000)),
          svHealth: 0,
          svAccuracy: 2.0,
          tgd: 0,
          iodc: 0,
          iode: 0,
          transmissionTime: 0,
          fitInterval: 4
        });
      }
    }
    
    return satellites;
  }
  
  static generateRinexFile(satellites, date) {
    const header = this.generateRinexHeader(date);
    const navigationRecords = satellites.map(sat => this.generateNavigationRecord(sat)).join('');
    
    return header + navigationRecords;
  }
  
  static generateRinexHeader(date) {
    const version = '2.11';
    const fileType = 'N';
    const system = 'GPS';
    const program = 'GPS_SAT_VIZ';
    const agency = 'USER';
    const creationDate = new Date().toISOString().replace(/[:-]/g, '').slice(0, 15);
    
    return `     ${version}           ${fileType}                   RINEX VERSION / TYPE
${program.padEnd(20)}${agency.padEnd(20)}${creationDate.padEnd(20)}PGM / RUN BY / DATE
GPS Satellite Constellation Visualization Tool                 COMMENT
Generated ephemeris data for visualization purposes            COMMENT
                                                            END OF HEADER
`;
  }
  
  static generateNavigationRecord(satellite) {
    const date = new Date(satellite.epoch);
    const year = date.getUTCFullYear().toString().slice(-2).padStart(2, '0');
    const month = (date.getUTCMonth() + 1).toString().padStart(2, '0');
    const day = date.getUTCDate().toString().padStart(2, '0');
    const hour = date.getUTCHours().toString().padStart(2, '0');
    const minute = date.getUTCMinutes().toString().padStart(2, '0');
    const second = date.getUTCSeconds().toString().padStart(2, '0');
    
    const prn = satellite.prn.toString().padStart(2, '0');
    const clockBias = this.formatScientific(satellite.clockBias || 0);
    const clockDrift = this.formatScientific(satellite.clockDrift || 0);
    const clockDriftRate = this.formatScientific(satellite.clockDriftRate || 0);
    
    let record = `${prn} ${year} ${month} ${day} ${hour} ${minute} ${second}.0${clockBias}${clockDrift}${clockDriftRate}\\n`;
    
    // Line 1: IODE, Crs, Delta n, M0
    record += `   ${this.formatScientific(satellite.iode || 0)}${this.formatScientific(satellite.crs || 0)}${this.formatScientific(satellite.deltaN || 0)}${this.formatScientific(satellite.meanAnomaly)}\\n`;
    
    // Line 2: Cuc, e, Cus, sqrt(A)
    record += `   ${this.formatScientific(satellite.cuc || 0)}${this.formatScientific(satellite.eccentricity)}${this.formatScientific(satellite.cus || 0)}${this.formatScientific(satellite.sqrtA)}\\n`;
    
    // Line 3: Toe, Cic, OMEGA, Cis
    record += `   ${this.formatScientific(satellite.toe || 0)}${this.formatScientific(satellite.cic || 0)}${this.formatScientific(satellite.raan)}${this.formatScientific(satellite.cis || 0)}\\n`;
    
    // Line 4: i0, Crc, omega, OMEGA DOT
    record += `   ${this.formatScientific(satellite.inclination)}${this.formatScientific(satellite.crc || 0)}${this.formatScientific(satellite.argOfPerigee)}${this.formatScientific(satellite.raanDot || 0)}\\n`;
    
    // Line 5: IDOT, Codes on L2, GPS Week, L2 P data flag
    record += `   ${this.formatScientific(satellite.inclinationDot || 0)}${this.formatScientific(satellite.codesOnL2 || 0)}${this.formatScientific(satellite.gpsWeek)}${this.formatScientific(satellite.l2PDataFlag || 0)}\\n`;
    
    // Line 6: SV accuracy, SV health, TGD, IODC
    record += `   ${this.formatScientific(satellite.svAccuracy || 0)}${this.formatScientific(satellite.svHealth || 0)}${this.formatScientific(satellite.tgd || 0)}${this.formatScientific(satellite.iodc || 0)}\\n`;
    
    // Line 7: Transmission time, fit interval
    record += `   ${this.formatScientific(satellite.transmissionTime || 0)}${this.formatScientific(satellite.fitInterval || 0)}                        \\n`;
    
    return record;
  }
  
  static formatScientific(value) {
    if (value === 0) return ' 0.000000000000D+00';
    
    const exp = Math.floor(Math.log10(Math.abs(value)));
    const mantissa = value / Math.pow(10, exp);
    const sign = value >= 0 ? ' ' : '';
    const expSign = exp >= 0 ? '+' : '';
    
    return `${sign}${mantissa.toFixed(12)}D${expSign}${Math.abs(exp).toString().padStart(2, '0')}`;
  }
}

export default RinexParser;
